const GlowingPulse = ({ y, x1, x2, pulseX, s, accentColor }: { y: number, x1: number, x2: number, pulseX: number, s: number, accentColor: string }) => {
  const pulseWidth = 140 * s;
  const pStart = pulseX - pulseWidth;
  const pEnd = pulseX;
  const drawStart = Math.max(x1, pStart);
  const drawEnd = Math.min(x2, pEnd);
  
  if (drawStart >= drawEnd) return null;
  
  return (
    <>
      <line x1={drawStart} x2={drawEnd} y1={y} y2={y} stroke="#FFFFFF" strokeWidth={4 * s} style={{ transition: 'none' }} strokeLinecap="round" />
      <line x1={drawStart} x2={drawEnd} y1={y} y2={y} stroke={accentColor} strokeWidth={10 * s} style={{ filter: `blur(${6 * s}px)`, transition: 'none' }} strokeLinecap="round" />
    </>
  );
};

const Card = ({ index, cx, cy, item, frame, s, accentColor, cardBackgroundColor, isFirst, isLast, fps }: any) => {
  const delay = 10 + index * 20;
  const progress = spring({ frame: frame - delay, fps, config: { damping: 14 } });
  
  const scale = progress;
  const opacity = interpolate(progress, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
  const glowStrength = interpolate(Math.sin((frame - delay) / 15), [-1, 1], [0.15, 0.45]);

  if (progress === 0) return null;

  const fontFam = item.titleFontFamily === "Space Grotesk" ? spaceFamily : item.titleFontFamily === "Roboto Mono" ? robotoMonoFamily : interFamily;
  const cardWidth = 220 * s;
  const cardHeight = 340 * s;

  return (
    <div style={{
      position: 'absolute',
      left: cx - cardWidth / 2,
      top: cy - cardHeight / 2,
      width: cardWidth,
      height: cardHeight,
      backgroundColor: cardBackgroundColor,
      borderRadius: 20 * s,
      border: `${2 * s}px solid ${cardBackgroundColor}`,
      boxShadow: `0 ${10 * s}px ${40 * s}px rgba(0,0,0,0.5)`,
      transform: `scale(${scale})`,
      opacity: opacity,
      transition: 'none',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
    }}>
      <div style={{ position: 'absolute', inset: 0, borderRadius: 20 * s, border: `${2 * s}px solid ${accentColor}`, opacity: 0.25, pointerEvents: 'none' }} />
      <div style={{ position: 'absolute', inset: 0, borderRadius: 20 * s, boxShadow: `inset 0 0 ${50 * s}px ${accentColor}`, opacity: glowStrength, pointerEvents: 'none' }} />
      
      <div style={{ marginTop: 40 * s, width: 80 * s, height: 80 * s, borderRadius: '50%', backgroundColor: accentColor, opacity: 0.1 }} />
      <div style={{ position: 'absolute', top: 40 * s, width: 80 * s, height: 80 * s, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
        {renderIcon(item.iconType, s, accentColor)}
      </div>

      <div style={{ marginTop: 24 * s, padding: `0 ${16 * s}px`, color: '#FFFFFF', fontSize: 22 * s, fontFamily: fontFam, fontWeight: 600, textAlign: 'center', lineHeight: 1.3, zIndex: 2 }}>
        {item.title}
      </div>

      <div style={{ marginTop: 'auto', marginBottom: 36 * s, width: 32 * s, height: 4 * s, backgroundColor: accentColor, borderRadius: 2 * s, boxShadow: `0 0 ${8 * s}px ${accentColor}`, zIndex: 2 }} />

      {/* Dots */}
      {!isFirst && (
        <div style={{ position: 'absolute', left: -8 * s, top: cardHeight / 2 - 8 * s, width: 16 * s, height: 16 * s, borderRadius: '50%', backgroundColor: cardBackgroundColor, border: `${3 * s}px solid ${accentColor}`, boxShadow: `0 0 ${10 * s}px ${accentColor}` }} />
      )}
      {!isLast && (
        <div style={{ position: 'absolute', right: -8 * s, top: cardHeight / 2 - 8 * s, width: 16 * s, height: 16 * s, borderRadius: '50%', backgroundColor: cardBackgroundColor, border: `${3 * s}px solid ${accentColor}`, boxShadow: `0 0 ${10 * s}px ${accentColor}` }} />
      )}
      <div style={{ position: 'absolute', left: cardWidth / 2 - 8 * s, bottom: -8 * s, width: 16 * s, height: 16 * s, borderRadius: '50%', backgroundColor: cardBackgroundColor, border: `${3 * s}px solid ${accentColor}`, boxShadow: `0 0 ${10 * s}px ${accentColor}` }} />
    </div>
  );
};

const SystemDiagram: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 12,
  accentColor = "#8CF21A",
  cardBackgroundColor = "#151A22",
  items = [
    { title: "Offer", titleFontFamily: "Inter", iconType: "Offer" },
    { title: "Appointment Booking", titleFontFamily: "Inter", iconType: "Calendar" },
    { title: "Sales", titleFontFamily: "Inter", iconType: "Chart" },
    { title: "Service Delivery", titleFontFamily: "Inter", iconType: "Settings" },
    { title: "Testimonials", titleFontFamily: "Inter", iconType: "Stars" },
    { title: "Premium Clients", titleFontFamily: "Inter", iconType: "Crown" }
  ]
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  const startX = 200 * s;
  const endX = width - 200 * s;
  const itemCount = items.length;
  const gapX = itemCount > 1 ? (endX - startX) / (itemCount - 1) : 0;
  
  const cx = items.map((_, i) => startX + i * gapX);
  const cy = 500 * s;
  const cardWidth = 220 * s;
  const cardHeight = 340 * s;
  const trackY = cy + cardHeight / 2 + 80 * s;

  const indices = items.map((_, i) => i);
  const segmentIndices = indices.slice(0, -1);

  const globalOpacity = interpolate(frame, [fps * durationInSeconds - 30, fps * durationInSeconds], [1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const pulse1X = interpolate(frame, [150, 210], [startX - 300 * s, endX + 300 * s], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const pulse2X = interpolate(frame, [240, 300], [startX - 300 * s, endX + 300 * s], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, opacity: globalOpacity, transition: 'none' }}>
      <svg width={width} height={height} style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
        
        {/* Middle Connecting Lines */}
        {segmentIndices.map(i => {
          const delay = 20 + i * 20;
          const progress = spring({ frame: frame - delay, fps, config: { damping: 20 } });
          const x1 = cx[i] + cardWidth / 2;
          const x2 = cx[i + 1] - cardWidth / 2;
          const currentX2 = interpolate(progress, [0, 1], [x1, x2]);
          if (progress === 0) return null;
          return <line key={`mid-${i}`} x1={x1} x2={currentX2} y1={cy} y2={cy} stroke={accentColor} strokeWidth={2 * s} />;
        })}

        {/* Bottom Horizontal Track */}
        {segmentIndices.map(i => {
          const delay = 20 + i * 20;
          const progress = spring({ frame: frame - delay, fps, config: { damping: 20 } });
          const currentX2 = interpolate(progress, [0, 1], [cx[i], cx[i + 1]]);
          if (progress === 0) return null;
          return <line key={`bot-${i}`} x1={cx[i]} x2={currentX2} y1={trackY} y2={trackY} stroke={accentColor} strokeWidth={2 * s} />;
        })}

        {/* Vertical Drops */}
        {indices.map(i => {
          const delay = 10 + i * 20;
          const progress = spring({ frame: frame - delay, fps, config: { damping: 20 } });
          const y1 = cy + cardHeight / 2;
          const currentY2 = interpolate(progress, [0, 1], [y1, trackY]);
          if (progress === 0) return null;
          return <line key={`vert-${i}`} x1={cx[i]} x2={cx[i]} y1={y1} y2={currentY2} stroke={accentColor} strokeWidth={2 * s} />;
        })}

        {/* Bottom Track Junction Dots */}
        {indices.map(i => {
          const delay = 20 + i * 20;
          const progress = spring({ frame: frame - delay, fps, config: { damping: 15 } });
          if (progress === 0) return null;
          return (
            <circle key={`dot-${i}`} cx={cx[i]} cy={trackY} r={6 * s * progress} fill={cardBackgroundColor} stroke={accentColor} strokeWidth={3 * s} />
          );
        })}

        {/* Momentum Pulses */}
        {segmentIndices.map(i => {
          const lineX1 = cx[i] + cardWidth / 2;
          const lineX2 = cx[i + 1] - cardWidth / 2;
          return (
            <React.Fragment key={`pulse-mid-${i}`}>
              <GlowingPulse y={cy} x1={lineX1} x2={lineX2} pulseX={pulse1X} s={s} accentColor={accentColor} />
              <GlowingPulse y={cy} x1={lineX1} x2={lineX2} pulseX={pulse2X} s={s} accentColor={accentColor} />
            </React.Fragment>
          );
        })}

        {itemCount > 1 && (
          <>
            <GlowingPulse y={trackY} x1={cx[0]} x2={cx[itemCount - 1]} pulseX={pulse1X} s={s} accentColor={accentColor} />
            <GlowingPulse y={trackY} x1={cx[0]} x2={cx[itemCount - 1]} pulseX={pulse2X} s={s} accentColor={accentColor} />
          </>
        )}
      </svg>

      {/* Foreground Cards */}
      {indices.map(i => (
        <Card 
          key={i} 
          index={i} 
          cx={cx[i]} 
          cy={cy} 
          item={items[i]} 
          frame={frame} 
          s={s} 
          accentColor={accentColor} 
          cardBackgroundColor={cardBackgroundColor} 
          isFirst={i === 0}
          isLast={i === itemCount - 1}
          fps={fps}
        />
      ))}
    </AbsoluteFill>
  );
};

export default SystemDiagram;